package com.example.application_service.exception;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.UUID;import java.util.regex.Pattern;
@Component @Order(Ordered.HIGHEST_PRECEDENCE) public class CorrelationIdFilter extends OncePerRequestFilter{public static final String HEADER="X-Correlation-ID",ATTRIBUTE=CorrelationIdFilter.class.getName()+".id";private static final Pattern VALID=Pattern.compile("[A-Za-z0-9._-]{1,128}");protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String v=req.getHeader(HEADER);String id=v!=null&&VALID.matcher(v).matches()?v:UUID.randomUUID().toString();req.setAttribute(ATTRIBUTE,id);res.setHeader(HEADER,id);chain.doFilter(req,res);}}
